package main

import "fmt"

type Counter struct {
	Name string
	n    int
}

func (c *Counter) Inc() {
	c.n++
}

func (c *Counter) Get() int {
	return c.n
}

func main() {
	// 指针接收者改状态
	c := &Counter{Name: "点击"}
	c.Inc()
	c.Inc()
	fmt.Println(c.Name, c.Get())

	// 取地址与解引用
	x := 10
	p := &x
	*p = 20
	fmt.Println(x, *p)

	// nil 要先判再解引用
	var np *int
	if np != nil {
		fmt.Println(*np)
	} else {
		fmt.Println("np 为 nil")
	}

	// new 分配零值并返回指针
	q := new(int)
	*q = 7
	fmt.Println(*q)

	// 指针作 map 的键
	m := map[*Counter]string{}
	m[c] = "同一个计数器"
	fmt.Println(m[c])

	// 指向数组元素
	arr := [3]int{1, 2, 3}
	ap := &arr[1]
	*ap = 200
	fmt.Println(arr)

	// 指向切片元素
	s := []int{4, 5, 6}
	sp := &s[0]
	*sp = 40
	fmt.Println(s)
}
